/** Production URL (Vercel project domain). */
const PRODUCTION_URL = "https://sanskar-kumar.vercel.app";

/**
 * Public origin of the site, used for canonical URLs, Open Graph, structured
 * data, robots.txt, the sitemap and llms.txt. Set VITE_SITE_URL at build time
 * only to override it, e.g. after moving to a custom domain.
 */
export const SITE_URL = (import.meta.env.VITE_SITE_URL ?? PRODUCTION_URL).replace(/\/+$/, "");

/** Open Graph / Twitter card image (1200 × 630), generated by scripts/og-image.ts. */
export const OG_IMAGE = { path: "/og.png", width: 1200, height: 630 } as const;

/** Google Search Console token (HTML tag method) for the URL-prefix property of PRODUCTION_URL. Public by design. */
const GOOGLE_SITE_VERIFICATION = "oaHxwJKElwXKlQ6uc_v6uOiJJe7FwHUiWkUvsfQFXPc";

/**
 * Search-engine ownership tokens (HTML tag method), rendered as <meta> tags in
 * the root layout only when set. Env vars override the defaults (e.g. for a
 * custom domain); empty strings count as unset.
 */
export const SITE_VERIFICATION = [
  {
    name: "google-site-verification",
    content: import.meta.env.VITE_GOOGLE_SITE_VERIFICATION ?? GOOGLE_SITE_VERIFICATION,
  },
  { name: "msvalidate.01", content: import.meta.env.VITE_BING_SITE_VERIFICATION },
].filter((tag): tag is { name: string; content: string } => Boolean(tag.content?.trim()));

export const absoluteUrl = (path = "/") => new URL(path, `${SITE_URL}/`).toString();
